```cpp
#include <iostream>
#include <string>
#include <pugixml.hpp>

// Function to convert Markdown to HTML
std::string markdown_to_html(const std::string& markdown) {
    // Create a PugiXML document and load the Markdown input
    pugi::xml_document doc;
    pugi::xml_parse_result result = doc.load_string(markdown.c_str());

    if (!result) {
        std::cerr << "Error parsing Markdown input: " << result.description() << std::endl;
        return ""; // Return empty string on parsing error
    }

    // Convert Markdown to HTML using PugiXML's built-in Markdown support
    pugi::xml_node root_node = doc.document_element();
    std::string html;
    if (root_node.type() == pugi::node_document) {
        root_node = root_node.child("body");
    }
    if (root_node.type() == pugi::node_element) {
        pugi::xml_writer_settings settings;
        settings.indent("  ");
        settings.line_separator('\n');
        doc.save(html.c_str(), settings);
    } else {
        std::cerr << "Error: expected a 'body' element in the input document" << std::endl;
        return ""; // Return empty string on unexpected document structure
    }

    return html;
}

int main() {
    std::string markdown = "# Hello World\n\nThis is some **bold** and _italic_ text.";
    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

