int main(int argc, char *argv[]) {
    Game game;

    // Initialize the game
    InitGame(&game);

    // Load images
    LoadImages(&game);

    // Game loop
    while (game.game_state == GameStateRunning) {
        // Handle input
        HandleInput(&game);

        // Update game logic
        UpdateGame(&game);

        // Render the game
        RenderGame(&game);

        // Limit the frame rate
        SDL_Delay((1000 / game.frame_rate) - (SDL_GetTicks() - game.start_ticks));
        game.start_ticks = SDL_GetTicks();
    }

    // Game over
    if (game.game_state == GameStateGameOver) {
        printf("Game over!\n");
    }

    // Free resources
    FreeGame(&game);

    return 0;
}

void InitGame(Game *game) {
    // Initialize SDL
    SDL_Init(SDL_INIT_VIDEO);

    // Create window
    game->window = SDL_CreateWindow("Snake",
                                     SDL_WINDOWPOS_CENTERED,
                                     SDL_WINDOWPOS_CENTERED,
                                     BOARD_WIDTH,
                                     BOARD_HEIGHT,
                                     SDL_WINDOW_SHOWN);

    // Create renderer
    game->renderer = SDL_CreateRenderer(game->window, -1, SDL_RENDERER_ACCELERATED);

    // Set up background
    game->background_surface = SDL_LoadBMP("background.bmp");
    game->background_texture = SDL_CreateTextureFromSurface(game->renderer, game->background_surface);
    SDL_FreeSurface(game->background_surface);

    // Set up snake images
    game->snake_head_surface = SDL_LoadBMP("snake_head.bmp");
    game->snake_head_texture = SDL_CreateTextureFromSurface(game->renderer, game->snake_head_surface);
    SDL_FreeSurface(game->snake_head_surface);

    game->snake_body_surface = SDL_LoadBMP("snake_body.bmp");
    game->snake_body_texture = SDL_CreateTextureFromSurface(game->renderer, game->snake_body_surface);
    SDL_FreeSurface(game->snake_body_surface);

    // Set up food image
    game->food_surface = SDL_LoadBMP("food.bmp");
    game->food_texture = SDL_CreateTextureFromSurface(game->renderer, game->food_surface);
    SDL_FreeSurface(game->food_surface);

    // Initialize game state
    game->snake_length = 3;
    game->score = 0;
    game->food_x = rand() % ((BOARD_WIDTH / IMAGE_SIZE) - 2) + 1;
    game->food_y = rand() % ((BOARD_HEIGHT / IMAGE_SIZE) - 2) + 1;
    game->game_state = GameStateRunning;
    game->frame_rate = 60;
    game->start_ticks = SDL_GetTicks();
}

void LoadImages(Game *game) {
    SDL_Surface *loaded_image;
    SDL_Rect image_rect;

    image_rect.w = IMAGE_SIZE;
    image_rect.h = IMAGE_SIZE;

    // Snake head
    loaded_image = SDL_LoadBMP("snake_head.bmp");
    SDL_SetColorKey(loaded_image, SDL_TRUE, SDL_MapRGB(loaded_image->format, 0xFF, 0xFF, 0xFF));
    game->snake_head_surface = loaded_image;

    // Snake body
    loaded_image = SDL_LoadBMP("snake_body.bmp");
    SDL_SetColorKey(loaded_image, SDL_TRUE, SDL_MapRGB(loaded_image->format, 0xFF, 0xFF, 0xFF));
    game->snake_body_surface = loaded_image;

    // Food
    loaded_image = SDL_LoadBMP("food.bmp");
    SDL_SetColorKey(loaded_image, SDL_TRUE, SDL_MapRGB(loaded_image->format, 0xFF, 0xFF, 0xFF));
    game->food_surface = loaded_image;

    SDL_FreeSurface(loaded_image);
}

void UpdateGame(Game *game) {
    // Move snake
    int new_x, new_y;
    SnakeSegment *tail = &game->snake[game->snake_length - 1];

    switch (game->snake[0].direction) {
        case SDL_SCANCODE_UP:
            new_x = game->snake[0].x;
            new_y = game->snake[0].y - IMAGE_SIZE;
            break;
        case SDL_SCANCODE_DOWN:
            new_x = game->snake[0].x;
            new_y = game->snake[0].y + IMAGE_SIZE;
            break;
        case SDL_SCANCODE_LEFT:
            new_x = game->snake[0].x - IMAGE_SIZE;
            new_y = game->snake[0].y;
            break;
        case SDL_SCANCODE_RIGHT:
            new_x = game->snake[0].x + IMAGE_SIZE;
            new_y = game->snake[0].y;
            break;
    }

    // Check for collision with walls or tail
    if (new_x < 0 || new_x >= (BOARD_WIDTH / IMAGE_SIZE) ||
        new_y < 0 || new_y >= (BOARD_HEIGHT / IMAGE_SIZE) ||
        CheckCollision(game->snake, game->snake_length, new_x, new_y)) {
        game->game_state = GameStateGameOver;
        return;
    }

    // Add new segment to snake
    for (int I = game->snake_length - 1; I > 0; --i) {
        game->snake[i].x = game->snake[i - 1].x;
        game->snake[i].y = game->snake[i - 1].y;
        game->snake[i].prev_x = game->snake[i - 1].x;
        game->snake[i].prev_y = game->snake[i - 1].y;
    }

    game->snake[0].x = new_x;
    game->snake[0].y = new_y;

    // Spawn new food
    int food_spawned = 0;
    while (!food_spawned) {
        game->food_x = rand() % ((BOARD_WIDTH / IMAGE_SIZE) - 2) + 1;
        game->food_y = rand() % ((BOARD_HEIGHT / IMAGE_SIZE) - 2) + 1;

        food_spawned = !CheckCollision(game->snake, game->snake_length, game->food_x, game->food_y);
    }

    // Increase score
    if (new_x == game->food_x && new_y == game->food_y) {
        game->score++;
        game->snake_length++;
    }
}

void RenderGame(Game *game) {
    SDL_Rect rect;

    // Clear the screen
    SDL_SetRenderDrawColor(game->renderer, 0x00, 0x00, 0x00, SDL_ALPHA_OPAQUE);
    SDL_RenderClear(game->renderer);

    // Draw background
    rect.x = 0;
    rect.y = 0;
    rect.w = BOARD_WIDTH;
    rect.h = BOARD_HEIGHT;
    SDL_RenderCopy(game->renderer, game->background_texture, NULL, &rect);

    // Draw snake
    for (int I = 0; I < game->snake_length; ++i) {
        rect.x = game->snake[i].x * IMAGE_SIZE;
        rect.y = game->snake[i].y * IMAGE_SIZE;
        rect.w = IMAGE_SIZE;
        rect.h = IMAGE_SIZE;

        if (i == 0) {
            SDL_RenderCopy(game->renderer, game->snake_head_texture, NULL, &rect);
        } else {
            SDL_RenderCopy(game->renderer, game->snake_body_texture, NULL, &rect);
        }

        // Draw interpolation line between previous and current position
        SDL_SetRenderDrawColor(game->renderer, 0xFF, 0x00, 0x00, SDL_ALPHA_OPAQUE);
        SDL_RenderDrawLine(game->renderer, game->snake[i].prev_x * IMAGE_SIZE + IMAGE_SIZE / 2,
                            game->snake[i].prev_y * IMAGE_SIZE + IMAGE_SIZE / 2,
                            game->snake[i].x * IMAGE_SIZE + IMAGE_SIZE / 2,
                            game->snake[i].y * IMAGE_SIZE + IMAGE_SIZE / 2);
    }

    // Draw food
    rect.x = game->food_x * IMAGE_SIZE;
    rect.y = game->food_y * IMAGE_SIZE;
    rect.w = IMAGE_SIZE;
    rect.h = IMAGE_SIZE;
    SDL_RenderCopy(game->renderer, game->food_texture, NULL, &rect);

    // Draw score
    char score_text[64];
    sprintf(score_text, "Score: %d", game->score);
    SDL_SetRenderDrawColor(game->renderer, 0xFF, 0xFF, 0xFF, SDL_ALPHA_OPAQUE);
    SDL_RenderDrawFilledRect(game->renderer, 10, 10, 80, 20);
    SDL_SetRenderDrawColor(game->renderer, 0x00, 0x00, 0x00, SDL_ALPHA_OPAQUE);
    SDL_RenderDrawRect(game->renderer, 9, 9, 81, 21);
    SDL_SetTextureColorMod(game->renderer, 255, 255, 255);
    SDL_RenderText(game->renderer, score_text, 20, 20);

    // Update the screen
    SDL_RenderPresent(game->renderer);
}

void HandleInput(Game *game) {
    SDL_Event event;

    while (SDL_PollEvent(&event)) {
        if (event.type == SDL_KEYDOWN) {
            switch (event.key.keysym.sym) {
                case SDLK_UP:
                    game->snake[0].direction = SDL_SCANCODE_UP;
                    break;
                case SDLK_DOWN:
                    game->snake[0].direction = SDL_SCANCODE_DOWN;
                    break;
                case SDLK_LEFT:
                    game->snake[0].direction = SDL_SCANCODE_LEFT;
                    break;
                case SDLK_RIGHT:
                    game->snake[0].direction = SDL_SCANCODE_RIGHT;
                    break;
                case SDLK_p:
                    game->frame_rate += 10;
                    break;
                case SDLK_m:
                    game->frame_rate -= 10;
                    break;
            }
        } else if (event.type == SDL_QUIT) {
            game->game_state = GameStateGameOver;
        }
    }
}

void FreeGame(Game *game) {
    SDL_DestroyTexture(game->background_texture);
    SDL_FreeSurface(game->snake_head_surface);
    SDL_FreeSurface(game->snake_body_surface);
    SDL_FreeSurface(game->food_surface);
    SDL_DestroyRenderer(game->renderer);
    SDL_DestroyWindow(game->window);
    SDL_Quit();
}

bool CheckCollision(SnakeSegment *snake, int snake_length, int x, int y) {
    for (int I = 0; I < snake_length; ++i) {
        if (snake[i].x == x && snake[i].y == y) {
            return true;
        }
    }
    return false;
}
